import{_ as s,o as i,c as t,a2 as a}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"faqs.md","filePath":"faqs.md"}'),n={name:"faqs.md"};function o(r,e,l,h,p,d){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="faqs" tabindex="-1">FAQs <a class="header-anchor" href="#faqs" aria-label="Permalink to &quot;FAQs&quot;">​</a></h1><h2 id="what-is-saml" tabindex="-1">What is SAML? <a class="header-anchor" href="#what-is-saml" aria-label="Permalink to &quot;What is SAML?&quot;">​</a></h2><p>Answer: <a href="https://en.wikipedia.org/wiki/Security_Assertion_Markup_Language" target="_blank" rel="noreferrer">Here&#39;s wikipedia&#39;s answer</a></p><blockquote><p>Security Assertion Markup Language (SAML, pronounced SAM-el) is an open standard for exchanging authentication and authorization data between parties, in particular, between an identity provider and a service provider. SAML is an XML-based markup language for security assertions (statements that service providers use to make access-control decisions). SAML is also:</p><ul><li>A set of XML-based protocol messages</li><li>set of protocol message bindings</li><li>set of profiles (utilizing all of the above)</li><li>The single most important use case that SAML addresses is web browser single sign-on (SSO). Single sign-on is relatively easy to accomplish within a security domain (using cookies, for example) but extending SSO across security domains is more difficult and resulted in the proliferation of non-interoperable proprietary technologies. The SAML Web Browser SSO profile was specified and standardized to promote interoperability.</li></ul></blockquote><div class="tip custom-block"><p class="custom-block-title">TIP</p><h3 id="saml-sp-101" tabindex="-1">SAML SP 101 <a class="header-anchor" href="#saml-sp-101" aria-label="Permalink to &quot;SAML SP 101&quot;">​</a></h3><p>This plugin is concerned with the Service Provider (SP) site. It&#39;s role is to receive authentication and authorization messages from the Identity Provider (IdP). Upon a successful IdP login, a message login status (success or not), session info, and user attributes are POSTed (usually POST, sometimes GET) to the Craft site and received and validated by the plugin. Then the user is synced, logged in, and redirected to where the user initially intended to go.</p></div><h2 id="what-is-the-entity-id" tabindex="-1">What is the Entity ID? <a class="header-anchor" href="#what-is-the-entity-id" aria-label="Permalink to &quot;What is the Entity ID?&quot;">​</a></h2><p>An entity ID is a globally unique name for a SAML entity, either an Identity Provider (IdP) or a Service Provider (SP). Recent plugin updates has made it so Entity ID is editable but be careful when doing so -- the other providers may still have that ID as their link to yours.</p><h2 id="is-there-multi-site-support" tabindex="-1">Is there <a href="https://docs.craftcms.com/v3/sites.html" target="_blank" rel="noreferrer">Multi-Site</a> support? <a class="header-anchor" href="#is-there-multi-site-support" aria-label="Permalink to &quot;Is there [Multi-Site](https://docs.craftcms.com/v3/sites.html) support?&quot;">​</a></h2><p>Answer: Yes, as of 2.0.1, a multi-site configuration should work seamlessly.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Multi-Site When you create &quot;My Provider&quot;, the Entity ID and endpoints default to the current site. This should not create any problems. If the appearance is a aesthetic issue for whatever reason, use the Primary site when creating &quot;My Provider&quot;. You can also override the default Entity Id if desired.</p></div><h2 id="does-the-plugin-support-a-metadata-url" tabindex="-1">Does the plugin support a metadata URL? <a class="header-anchor" href="#does-the-plugin-support-a-metadata-url" aria-label="Permalink to &quot;Does the plugin support a metadata URL?&quot;">​</a></h2><p>Answer: Yes, as of version 2.1. If you use providers like ADFS who periodically renew their metadata and certificates, you can automate the syncing by running the following command:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saml-sp/metadata/refresh-with-url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>An example cronjob would look like this:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saml-sp/metadata/refresh-with-url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /opt/notify-admins-on-fail.sh</span></span></code></pre></div><h2 id="signature-required-but-not-found" tabindex="-1">Signature required but not found <a class="header-anchor" href="#signature-required-but-not-found" aria-label="Permalink to &quot;Signature required but not found&quot;">​</a></h2><p>Answer: By default for security reasons, the plugin requires signatures for both the Response and the Assertion. If these are not found you&#39;ll see an error &quot;Signature required but not found: Response&quot; or &quot;Signature required but not found: Assertion&quot;. You can modify the settings of this require (at your own risk) by setting the <code>config/saml-sp.php</code> config file with (found in class <code>\\flipbox\\saml\\sp\\models\\Settings</code>) the following settings:</p><ul><li><code>requireAssertionToBeSigned</code></li><li><code>requireResponseToBeSigned</code></li></ul><p>An example config file looks like the following:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // assertion is required but not the response</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;requireResponseToBeSigned&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Recommended It is recommended to have both or at least one of the two (Response or Assertion) for security purposes. The signature helps validate the message is from the trusted Identity Provider.</p></div><h2 id="error-trying-to-get-property-keychain-of-non-object" tabindex="-1">Error: Trying to get property &#39;keychain&#39; of non-object <a class="header-anchor" href="#error-trying-to-get-property-keychain-of-non-object" aria-label="Permalink to &quot;Error: Trying to get property &#39;keychain&#39; of non-object&quot;">​</a></h2><p>Answer: This usually means &quot;My Provider&quot;, the sites metadata/provider can&#39;t be found, or possibly, hasn&#39;t been created. Go to <code>https://&lt;your domain&gt;/admin/saml-sp/metadata/my-provider</code> and create a new provider for your site.</p>`,23)])])}const k=s(n,[["render",o]]);export{c as __pageData,k as default};
